def run():
    from qgis.core import QgsProject
    layers = QgsProject.instance().mapLayersByName('smoke_points')
    if not layers:
        return {"success": False, "message": "smoke_points layer not found"}
    layer = layers[0]
    idx = layer.fields().indexOf('tmp1')
    if idx == -1:
        return {"success": False, "message": "Field 'tmp1' not found on smoke_points"}
    layer.startEditing()
    success = layer.deleteAttribute(idx)
    layer.commitChanges()
    return {"success": success, "removed_field": "tmp1"}
